import sys
from collections import Counter

def main():
    s = sys.stdin.readline().rstrip('\n')
    cnt = Counter(s)
    for i, ch in enumerate(s):
        if cnt[ch] == 1:
            sys.stdout.write(str(i) + '\n')
            return
    sys.stdout.write('-1\n')

if __name__ == "__main__":
    main()
